import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, UsageMetadata} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

const createSession = (content: string): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content, timestamp: SENT_AT}],
});

const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let round = 0;

  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      for (const chunk of rounds[round++] ?? []) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const lookupRegistry = (): ToolRegistry => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
    async () => ({result: 'found'})
  );
  return registry;
};

const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('ChatOrchestrator afterModelResponse usage across tool rounds', () => {
  it('accumulates usage across two tool rounds covering every provider call in the turn', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 10, outputTokens: 4, totalTokens: 14};
    const round2Usage: UsageMetadata = {inputTokens: 25, outputTokens: 8, totalTokens: 33};
    const round3Usage: UsageMetadata = {inputTokens: 40, outputTokens: 12, totalTokens: 52};
    let reported: UsageMetadata | undefined;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        reported = usage;
      },
    };
    const orchestrator = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round2Usage}],
        [{type: 'text', text: 'all done'}, {type: 'stop', stopReason: 'end_turn', usage: round3Usage}],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );

    await orchestrator.processMessage(createSession('ask'));

    expect(reported).toEqual({inputTokens: 75, outputTokens: 24, totalTokens: 99});
  });

  it('counts the rounds that reported usage when other rounds report none, and reports undefined when no round reported', async () => {
    const round1Usage: UsageMetadata = {inputTokens: 12, outputTokens: 5, totalTokens: 17};
    const round3Usage: UsageMetadata = {inputTokens: 30, outputTokens: 9, totalTokens: 39};
    const seen: Array<UsageMetadata | undefined> = [];
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, _text, usage) => {
        seen.push(usage);
      },
    };
    const partial = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use', usage: round1Usage}],
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
        [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn', usage: round3Usage}],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );
    const none = createChatOrchestrator(
      scriptedProvider([
        [TOOL_CALL, {type: 'stop', stopReason: 'tool_use'}],
        [{type: 'text', text: 'done'}, {type: 'stop', stopReason: 'end_turn'}],
      ]),
      promptBuilder,
      lookupRegistry(),
      {hooks}
    );

    await partial.processMessage(createSession('ask'));
    await none.processMessage(createSession('ask'));

    expect(seen).toEqual([{inputTokens: 42, outputTokens: 14, totalTokens: 56}, undefined]);
  });
});

